.preloader-wrapper-1 {
  align-items: center;
  position: fixed;
  z-index: 999999;
  left: 0px;
  top: 0px;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  transition: all 2s ease 2s;
  background-position: center center;
  background-size: 150px;
  background-repeat: no-repeat;
  backdrop-filter: blur(10px);
  background: #fff;
  /* From Uiverse.io by Shoh2008 */
}
.preloader-wrapper-1 .loader {
  width: 48px;
  height: 48px;
  display: block;
  margin: 20px auto;
  position: relative;
  color: #FFF;
  box-sizing: border-box;
  animation: rotation_19 2s linear infinite;
}
.preloader-wrapper-1 .loader::after,
.preloader-wrapper-1 .loader::before {
  content: "";
  box-sizing: border-box;
  position: absolute;
  width: 24px;
  height: 24px;
  top: 0;
  background-color: var(--bs-secondary);
  border-radius: 50%;
  animation: scale50 1s infinite ease-in-out;
}
.preloader-wrapper-1 .loader::before {
  top: auto;
  bottom: 0;
  background-color: var(--bs-primary);
  animation-delay: 0.5s;
}
@keyframes rotation_19 {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
@keyframes scale50 {
  0%, 100% {
    transform: scale(0);
  }
  50% {
    transform: scale(1);
  }
}

.loader {
  margin: 30px auto 0;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
}

.load-circle {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.load-circle .circle-2 {
  width: 120px;
  height: 120px;
  position: absolute;
  border: 2px solid var(--rgba-primary-4);
  opacity: 1;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.load-circle .circle-2 img {
  max-width: 55px;
}
.load-circle .circle-2::after {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  border: 2px solid var(--bs-primary);
  border-radius: 50%;
  top: 50%;
  left: 50%;
  z-index: -1;
  transform: translate(-50%, -50%);
  animation: load-circle 1s ease-in-out infinite;
}
.load-circle .circle-2::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  border: 2px solid var(--bs-primary);
  border-radius: 50%;
  top: 50%;
  left: 50%;
  z-index: -1;
  transform: translate(-50%, -50%);
  animation: load-circle2 1s ease-in-out infinite;
}

@keyframes load-circle {
  0% {
    width: 0;
    height: 0;
    opacity: 0;
  }
  4.9% {
    width: 120px;
    height: 120px;
    opacity: 0;
  }
  5% {
    width: 120px;
    height: 120px;
    opacity: 1;
  }
  100% {
    width: 200px;
    height: 200px;
    opacity: 0;
  }
}
@keyframes load-circle2 {
  0% {
    width: 0;
    height: 0;
    opacity: 0;
  }
  4.9% {
    width: 120px;
    height: 120px;
    opacity: 0;
  }
  5% {
    width: 120px;
    height: 120px;
    opacity: 1;
  }
  100% {
    width: 160px;
    height: 160px;
    opacity: 0;
  }
}
@keyframes animate {
  0%, 100% {
    transform: rotate(-20deg);
  }
  50% {
    transform: rotate(20deg);
  }
}
@keyframes animate1 {
  0%, 100% {
    transform: rotate(0);
    left: 0;
  }
  50% {
    transform: rotate(200deg);
    left: calc(100% - 40px);
  }
}
@keyframes animate2 {
  0% {
    transform: rotate(0deg);
  }
  50% {
    transform: rotate(90deg);
  }
  100% {
    transform: rotate(0deg);
  }
}
@keyframes animateball {
  0% {
