.word-rotate-box {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 180px;
  height: 180px;
  background: transparent;
  border-radius: 100%;
  animation: identifier 20s linear infinite;
  text-align: center;
  padding: 15px;
  position: relative;
}
.word-rotate-box:after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  border-radius: 50%;
  border: 25px solid transparent;
}
.word-rotate-box .text__char {
  display: block;
  position: absolute;
  top: 10px;
  left: 10px;
  height: 80px;
  width: 160px;
  text-transform: uppercase;
  font-weight: 500;
  font-size: 16px;
  transform-origin: bottom center;
  transform: rotate(var(--char-rotate));
  color: #000;
}
.word-rotate-box i {
  display: block;
  margin: 0;
  animation: identifier 20s linear infinite;
  animation-direction: reverse;
  transition: all 0.3s;
  color: #000;
  font-size: 24px;
}
