/* Scroll Button Styling */
#scrollProgress {
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 40px;
  height: 40px;
  background-color: #000; /* or #f1f1f1 for light */
  color: #fff;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s ease;
  z-index: 999;
}

/* Show button on scroll */
#scrollProgress.show {
  opacity: 1;
  pointer-events: auto;
}

/* Icon Styling */
#scrollProgress .icon {
  position: relative;
  z-index: 2;
  font-size: 14px;
}

/* Progress Circle */
.progress-ring {
  position: absolute;
  top: 0;
  left: 0;
  transform: rotate(-90deg);
  z-index: 1;
}

.progress-ring circle {
  stroke: white;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-dasharray: 106.76;
  stroke-dashoffset: 106.76;
  transition: stroke-dashoffset 0.3s ease;
}

